func (b *BulkResolver) Resolve(ctx, host) (result BulkResult) {
    result.Host = host
    policy := b.retry
    for attempt := 1; attempt <= policy.MaxAttempts; attempt++ {
        if ctx.Err() != nil { result.Err = ctx.Err(); ... return }
        r := b.pool.next()
        data, err := r.client.QueryMultiple(host, b.questionTypes)
        r.report(err, data)
        result.Attempts = attempt
        b.stats.queries.Add(1)
        if !shouldRetry(data, err) {
            if data != nil && data.Host != "" {
                DedupeDNSData(data)
                result.Data = data
            }
            result.Err = err
            return
        }
        if attempt < policy.MaxAttempts {
            b.stats.retries.Add(1)
            select {
            case <-ctx.Done(): ...
            case <-time.After(policy.backoff(attempt)):
            }
        }
    }
    result.Err = ErrRetriesExceeded-ish
}
```

