func (b *BulkResolver) ResolveAll(ctx, hosts) <-chan BulkResult {
    out := make(chan BulkResult)
    go func() {
        defer close(out)
        jobs := make(chan string)
        var wg sync.WaitGroup
        for i := 0; i < concurrency; i++ {
            wg.Add(1)
            go func() {
                defer wg.Done()
                for host := range jobs {
                    res := b.Resolve(ctx, host)
                    b.stats.completed/failed...
                    select { case out <- *res: case <-ctx.Done(): return }
                }
            }()
        }
        seen := make(map[string]struct{}, len(hosts))
        feed:
        for _, h := range hosts {
            n := NormalizeHost(h)
            if n == "" || seen dup { continue }
            seen[n]=...
            select { case jobs <- n: case <-ctx.Done(): break feed }
        }
        close(jobs)
        wg.Wait()
    }()
    return out
}
